/**
 * Report 178 («сборка + патрон… бронежилеты и их плиты»): what a boss carries and how his armour is plated, from the game's
 * bot loadouts (about fifteen per bot). Generated by scripts/bosses/boss-gear.mjs into bossGear.json; PvP and PvE list
 * the same loadouts. The Gallery shows it in «Вооружение» and «Броня» (src/gallery/BossInfoPanel.tsx).
 */
import type { Bilingual } from './bossInfo'
import data from './bossGear.json'

/** [min, max] armour class; one class when three of four plates have it. */
export type ClassRange = readonly [number, number]

export interface BossGearItem { id: string; name: Bilingual }
export interface BossGearWeapon extends BossGearItem { ammo: BossGearItem[] }

export interface BossGearGroup {
  /** The maps of this kit, when the boss's kit differs by map (Black Division, The Wedge). */
  maps?: string[]
  /** This kit is on every map but the other groups' (Black Division's heavy kit). */
  elsewhere?: boolean
  weapons: BossGearWeapon[]
  /** Body armour and armoured rigs, the most worn first. */
  armor: BossGearItem[]
  /** Share of the loadouts with body armour, 0–1. */
  armored: number
  plates: { front?: ClassRange; back?: ClassRange; side?: ClassRange }
  helmet?: ClassRange
  helmetId?: string
  helmeted: number
  /** A face cover with armour (Tagilla's welding masks). */
  face?: ClassRange
}

export interface BossGear { groups: BossGearGroup[]; guards?: Omit<BossGearGroup, 'maps'> }

const GEAR = data as unknown as Record<string, BossGear>

export function bossGear(key: string): BossGear | undefined {
  return GEAR[key]
}

/** «6», «4–5». */
export function classLabel(range: ClassRange): string {
  return range[0] === range[1] ? String(range[0]) : `${range[0]}–${range[1]}`
}
